INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, baits_and_techniques, spawning_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Seabass, White ', 'White Weakfish, Seabass', 'The body of the white seabass is elongate, and somewhat compressed. The head is pointed and slightly compressed. The mouth is large, with a row of small teeth in the roof;

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, baits_and_techniques, spawning_lifecycle, diet_feeding_habits, water_body_type, avg_adult_weight, known_for, world_record, world_record_link)
VALUES ('Salt', 'Seatrout, Spotted ', 'Speckled Trout', 'The spotted seatrout has an elongated, silvery body with irregular black spots on the upper half and can grow to 39 inches long.

Despite their name, spotted seatrout are not actually trout. They are instead part of the drum fish family, named from the croaking, drumming noise they can make. 

', 'Sciaenidae', 'Cynoscion nebulosus', 'Least Concern', 'The spotted seatrout, also known as speckled trout (Cynoscion nebulosus), is a common estuarine fish found in the southern United States along coasts of Gulf of Mexico and South Atlantic Ocean. While most of these fish are caught on shallow, grassy flats, spotted seatrout reside in virtually any inshore waters, from the surf of outside islands to far up coastal rivers, where they often come for shelter during cold weather. Contrary to its name, the spotted seatrout is not a member of the trout family (Salmonidae), but of the drum family (Sciaenidae). It is popular for commercial and especially recreational fishing in coastal waters of the southeastern United States. Adults reach 19-25 inches in length and 3-17 pounds in weight.

Spotted seatrout live in the top of the water column and are most numerous along the coasts of the southeastern states, such as Texas, Louisiana, Alabama, Mississippi, Georgia, and Florida. They are also common along the coasts of North and South Carolina and Virginia. Estuarine coasts are prime settlement areas. They are uncommonly seen north of Delaware Bay and along the coast of Cape Cod, Massachusetts.

', 'While spotted seatrout are caught by both commercial and recreational fishermen, recreational fishing represents the vast majority of the catch. Almost all spotted seatrout are caught with hook and line, as many places have banned fishing for them with gillnets. The most common bait is shrimp, especially live shrimp, and larger trout prefer small bait fish such as menhaden. One catching technique, after dark, is to throw out a glow stick into the water and cast around it, as these fish are attracted to light (see Fishing light attractor).

According to the NOAA, spotted seatrout are in the top ten species for recreational fishing in the United States. From 1993 – 2003, recreational fishermen in Louisiana harvested more than 6 million spotted seatrout each year. Along the coasts of North Carolina and Virginia, more than half a million speckled trout were caught by recreational fishermen each year between 2005 and 2008. Nevertheless, because they reproduce so well, spotted seatrout is listed as a “best choice” for sustainable seafood in Louisiana and Florida by the Monterey Bay Aquarium''s Seafood Watch.', 'Like all members of the drum family, mature males make a "drumming" sound to attract females during the spawning season. Spotted seatrout have a long spawning season from spring through summer.', 'Small trout eat large amounts of shrimp and other crustaceans. As they grow larger, their diets shift toward fish, the larger, the better. Studies in Texas and Mississippi show that really big trout strongly prefer to feed on mullet;

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, baits_and_techniques, spawning_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Mackerel, Atlantic', 'Mackerel, Common Mackerel, Boston Mackerel, Caballa', 'Atlantic mackerel are iridescent blue green on the back with a silvery white underbelly. They have 20 to 30 wavy black bars that run across the top half of their body, and a narrow dark streak that runs below these bars along each side. Their body is spindle-shaped, tapering at both ends. The Atlantic Macker has two large dorsal fins that are typically gray or dusky. The pectoral fins are black or dusky at the base, and the tail fin is gray or dusky. Their distinctive coloring fades quickly after they die.', 'Scombridae', 'Scomber scombrus', 'Least Concern', 'Atlantic mackerel are common in cold and temperate waters over the continental shelf. They swim in schools near the surface, and travel to and from spawning and summering grounds.

 Atlantic mackerel are found on both sides of the North Atlantic Ocean, including the Baltic Sea. In the western Atlantic, they’re found from Labrador to North Carolina.', 'Trolling and casting are the top methods of fishing for Atlantic Mackerel. Light and ultra light spinning outfits or light fly rods are recommended. Atlantic mackerel are ravenous feeders that will eagerly take shrimp, crabs and other invertebrates as well as small baitfish. 

Atlantic mackerel will also accept a wide variety of artificial lures especially when densely schooling. Small bright spoons and metal squid are always a good choice as are small streamer flies tied with glittery skirts. Jigs and swimming plugs are other good choices when fishing for Atlantic mackerel.', 'Atlantic mackerel grow fast, up to 16 ½ inches and 2.2 pounds and can live up to 20 years. Atlantic mackerel are able to reproduce by the time they reach age 2 to 3.

There are two major spawning groups of Atlantic mackerel in the western Atlantic. The southern group spawns primarily in the Mid-Atlantic Bight from April to May. The northern group spawns in the Gulf of St. Lawrence in June and July. Both groups typically spawn 10 to 30 miles off shore.

Depending on their size, females can have between 285,000 and almost 2 million eggs. They release their eggs in batches, between five and seven times throughout the spawning season.

Eggs generally float in the surface water and hatch in 4 to 7.5 days, depending on water temperature.', 'Atlantic mackerel feed heavily on crustaceans such as copepods, krill, and shrimp. They also eat squid, as well as some fish and ascidians (sac-like marine invertebrate filter feeders).

Several species of fish and marine mammals also eat Atlantic mackerel.', 'Ocean', 'Speed', '2 lbs - 10 oz, 
Jorg Marquard, 
Kraakvaag Fjord, Norway,
6/29/1992', 'Atlantic Mackerel WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, baits_and_techniques, spawning_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Mackerel, King ', 'Kingfish, Carite, Carito', 'The king mackerel or kingfish (Scomberomorus cavalla) is a migratory species of mackerel of the western Atlantic Ocean and Gulf of Mexico. The king mackerel is a medium-sized fish, typically encountered from five to 30 lb (14 kg), but is known to exceed 90 lb (40 kg). 

The entire body is covered with very small, hardly visible, loosely attached scales. The first (spiny) dorsal fin is entirely colorless and is normally folded back into a body groove, as are the pelvic fins. The lateral line starts high on the shoulder, dips abruptly at mid-body and then continues as a wavy horizontal line to the tail. Coloration is olive on the back, fading to silver with a rosy iridescence on the sides, fading to white on the belly. Fish under 10 lb (5 kg) show yellowish-brown spots on the flanks, somewhat smaller than the spots of the Atlantic Spanish mackerel, Scomberomorus maculatus. Its cutting-edged teeth are large, uniform, closely spaced and flattened from side to side. These teeth look very similar to those of the bluefish, Pomatomus saltatrix.', 'Scombridae', 'Scomberomorus cavalla', 'Least Concern', 'The king mackerel is a subtropical species of the Atlantic Coast of the Americas. Common in the coastal zone from North Carolina to Brazil, it occurs as far south as Rio de Janeiro, and occasionally as far north as the Gulf of Maine. Nonetheless, a preference for water temperatures in the range of 68 to 84 °F (20 to 29 °C) may limit distribution.

King mackerel commonly occur in depths of 40–150 ft (12–45 m), where the principal fisheries occur. Larger kings (heavier than 20 lb or 9 kg) often occur inshore, in the mouths of inlets and harbors, and occasionally even at the 590 ft (180 m) depths at the edge of the Gulf Stream.

At least two migratory groups of king mackerel have been found to exist off the American coast. A Gulf of Mexico group ranges from the Texas coast in summer to the middle-east coast of Florida from November through March. Spawning occurs throughout the summer off the northern Gulf Coast.

An Atlantic group is abundant off North Carolina in spring and fall. This group migrates to southeast Florida, where it spawns from May through August, and slowly returns through summer. Apparently, this group winters in deep water off the Carolinas, as tagging studies have shown they are never found off Florida in winter.

', 'The most popular gear for king mackerel is light to medium ocean tackle with lines raining from 20-40 lb test, but Kings of all sizes can be caught on spinning, baitcasting and even fly tackle.

Surf tackle is the best choice for pier fishing. Spoons trolled behind planers are good, as are rigged cigar minnows and feather-minnow combinations. 

King mackerel respond well to chum, particularly chum containing ground bunker or menhaden oil.

Fishing with live bunker, herring, cigar minnows or sardines is likely the most productive approach of all, but drifting with rigged baits, strips or live shrimp can be effective too.', 'Eggs and sperm are shed into the sea and their union is by chance. Depending on size, a female may shed from 50,000 to several million eggs over the spawning season. 

Fertilized eggs hatch in about 24 hours. The newly hatched larva is about 2.5 mm (0.098 in) long with a large yolk sack. 

Little is known about king mackerel in their first year of life. Yearling fish typically attain an average weight of 3.1–4.0 lb (1.4–1.8 kg) and a fork length of 24 in (60 cm). 

At age seven, females average 22 lb (10 kg), males 11 lb (5 kg). King mackerel may attain weights of 88 lb (40 kg), but any over 15 lb (7 kg) is almost certainly a female.', 'King mackerel are voracious, opportunistic carnivores. Their prey depends on their size. 

Depending on area and season, they favor squid, menhaden and other sardine-like fish (Clupeidae), jacks (Carangidae), cutlassfish (Trichiuridae), weakfish (Sciaenidae), grunts (Haemulidae), striped anchovies (Engraulidae), cigar minnows, threadfin, northern mackerel, and blue runners. 

They do not attack humans but will defend themselves against perceived threats, including humans flailing or thrashing in man-overboard and similar situations, by biting.

', 'Ocean', 'Speed', '93 lb,
Steve Graulau,
San Juan, Puerto Rico,
4/18/1999', 'King Mackerel WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, baits_and_techniques, spawning_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Mackerel, Narrow-barred', 'Spanish Mackerel', 'The narrow-barred mackerel is vivid blue to dark grey in color along the back and flanks and fades to a silvery blue-grey on the belly. Spanish mackerel have several narrow, vertical dark lines that run down their sides reminiscent of zebra striping. Spanish mackerel are the largest of all Australian mackerels, growing to about 80 in (200 cm) and up to 150 lb (70 kg).', 'Scombridae', 'Scomberomorus commerson', 'Near Threatened', 'The narrow-barred mackerel is found in a wide area centering in Southeast Asia, but as far west as the east coast of Africa and from the Persian Gulf and along the northern coastal areas of the Indian Ocean, and as far east as Fiji in the South West Pacific ocean. They are common down both sides of Australia as far south as Perth on the west coast and Sydney on the east coast. They are also found as far north as China and even Japan.', 'When fishing for Spanish mackerel, use an outfit with an over head reel, 6-15kg line (depending on the fishing method) and a meter or so of heavy wire trace (Something like 25kg will do) to avoid and bust-offs on those sharp teeth. Chemically sharpened hooks are a good idea to get the hook to catch in the hard mouth of the Spanish mackerel. Two popular methods for catching Spanish mackerel are trolling from boats and ballooning from the shore.

Trolling can be done with hard-bodied minnow lures or live bait such as slimy mackerel, mullet or garfish secured with multiple hooks. Add a swivel to your rig for trolling and keep the speed below about seven knots. Ballooning involves filling a party balloon with air or helium and floating it above the swivel on a live or dead bait rig when an offshore wind is blowing.', 'Spanish mackerel spawn in oceanic conditions on reef edges. Eggs have a large oil droplet that aids in buoyancy and keeps them at the top of the water column which is warmer, well oxygenated, and has an abundant planktonic food supply for the larvae once they are hatched. 

When in the larval stage, Spanish mackerel are believed to stay in their own species-specific groups and are not normally found with other species of the same genus, such as S. semifasciatus and S. queenslandicus. This is not always the case with adult mackerel, where occasional mixing of different species within the same genus can occur.

Spawning is seasonal, but it is protracted in the warmer waters of the tropics. Many of the fisheries that target this species are based on prespawning feeding aggregations. A significant proportion of the female fish caught in NT waters between July and December have either recently spawned or are close to spawning. In general, spawning times for Spanish mackerel tend to be associated with higher water temperatures that promote optimal food availability for the rapid growth and development of the larvae.

As the young larvae grow, they move from the offshore spawning grounds to inshore and estuarine habitats, where they are frequently found in the juvenile phase of their growth cycle. In the inshore environments, they feed mostly on the larvae and juveniles of small fish and crustaceans until they become large enough to eat small fish and squid. Australian studies of this species suggest females are larger than males. Female Spanish mackerel mature at about two years of age or around 30 in (80 cm) in length.', 'Spanish mackerel are voracious, opportunistic carnivores. As with other members of the genus, food consists mainly of small fishes with lesser quantities of shrimp and squid.', 'Ocean', 'Speed', '99 lb,
Michael Wilkinson,
Scottburgh, Natal, South Africa,
3/14/1982', 'Narrow-barred Mackerel WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, baits_and_techniques, spawning_lifecycle, diet_feeding_habits, water_body_type, avg_adult_weight, avg_adult_length, known_for, world_record, world_record_link)
VALUES ('Salt', 'Tuna, Albacore', 'Albacore Fish, Albacore Tuna, Albicore, Albie, Pigfish, Tombo Ahi, Binnaga, Pacific Albacore, German Bonito, Bonito Longfin,Longfin Tuna, Longfin Tunny, Tuna', 'The albacore tuna''s pectoral fin is extremely long and extends well beyond the front of the anal fin except in tuna under 30 cm long. Its average size is about 1.4 m and can weigh up to 60 kg. 

The albacore''s fins consist of seven to 9 dorsal finlets, seven or eight anal finlets, and 25-31 gill rakers. This tuna is dark blue dorsally, and shades of silvery white ventrally. The first dorsal fin is a deep yellow. The second dorsal fin and the anal fin are a light yellow. The caudal fin is white-edged, while the anal finlets are dark.The albacore (Thunnus alalunga) is a species of tuna in the family Scombridae It is the only tuna species which may be marketed as "white meat tuna" in the United States. It is found in the open waters of all tropical and temperate oceans, and the Mediterranean Sea.

Albacore is a prized food, and the albacore fishery is economically significant. Methods of fishing include pole and line, long-line fishing, trolling, and some purse seining. It is also sought after by sport fishers.
', 'Scombridae', 'Thunnus alalunga', 'Near Threatened', 'The North Pacific Albacore migrate to two regions of the Northeast Pacific;

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, baits_and_techniques, spawning_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Tuna, Blackfin ', 'Bermuda Tuna, Blackfinned Albacore, Blackfin', 'Blackfin tuna (Thunnus atlanticus) are the smallest tuna species in the Thunnus genus, generally growing to a maximum of 100 cm (39 in) in length and weighing 21 kg (46 lbs).

They have oval-shaped bodies, black backs with a slight yellow on the finlets, and yellow on the sides of their bodies. They are only found in the western Atlantic from Cape Cod to Brazil.

Blackfin tuna are a short-lived, fast-growing species;

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, baits_and_techniques, spawning_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Tuna, Bluefin', 'Giant Bluefin Tuna, Northern Bluefin Tuna', 'The body of the bluefin tuna is rhomboidal in profile and robust. The head is conical and the mouth rather large. The head contains a "pineal window" that allows the fish to navigate over its multiple thousands of mile range.

The color is dark blue above and gray below with a gold coruscation covering the body and bright yellow caudal finlets. Bluefin tuna can be distinguished from other family members by the relatively short length of their pectoral fins. Their livers have a unique characteristic in that they are covered with blood vessels (striated). In other tunas with short pectoral fins, such vessels are either not present or present in small numbers along the edges.

Fully mature adult specimens average 6.6–8.2 ft long and weigh around 496–551 lb. The longest contest between man and tuna fish occurred near Liverpool, Nova Scotia in 1934, when six men taking turns fought a 796 lb tuna for sixty-two hours. Both the Smithsonian Institution and the National Marine Fish Service in North America have accepted that this species can weigh up to 2,010 lb, though further details are lacking. The world-record bluefin has remained unbroken since 1979, when Ken Fraser caught his 1,496-pounder off Nova Scotia.', 'Scombridae', 'Thunnus thynnus', 'Endangered', 'Bluefin are native to both the western and eastern Atlantic Ocean, Gulf of Mexico, Pacific Ocean, Indian Ocean as well as the Mediterranean Sea. Bluefin have become extinct in the Black Sea. The bluefin tuna is a close relative of the other two bluefin tuna species—the Pacific bluefin tuna and the southern bluefin tuna.', 'During the spring and summer the smaller version (20-50 lbs) is often found in 20-30 fathoms and therefor targeted by many smaller boats.  

Sometimes however larger bluefin pushing over 100 lbs can also be found hanging deeper in these same areas.  The smaller ones are usually targeted with Sterling Bars, Chains, Joe Shutes/ballyhoo and the old trusty 6” natural cedar plug on the flat line.   

Larger bluefin are typically caught trolling deeper lures like a 5 ¾ oz Joe Shutes with a ballyhoo way behind the boat (200-300 yds).  

Some anglers even run a 32-48oz drail 20’ ahead of the bait to really get it down. Slowing your speed to 5 knots will also allow the lures to sink deeper. 

When trolling, multiple hook ups is the ultimate goal. It is likely that you will only get 1-3 chances at tuna in a long 7 hour trolling day. Make each opportunity count. When you hook into a bluefin in a multiple rig troll pattern, do not immediately slow down and fight one fish, keep going around 20-30 seconds. During that time grab the line of lures that have not been bit and jig them forward and back, there is likely more tuna below that you are trying to bring up to attack your rigs.

As you slow down and clear the lines those tuna are still probably hanging around which can be a good time to drop a jig while waiting for another angler to bring the fish to the boat.

If your boat is creating a visible wake then it is advisable to troll your lures on top of the wakes and not in the trough. When trolling with spreading bars from your long rigger positions it is thought to be best if they are similar in color and size. This will give your spread a very wide appearance from below and will look like a more natural school of fish or sea creatures.

Try to match your lures to the size of the naturally occurring bait that the tuna are feeding upon. Small baitfish mean smaller lures, larger baitfish mean larger lures. You can sometimes discover this by checking the stomach contents of you first fish.

Most tuna fisherman set there reels to a strike drag of 13-21 lbs. There are varying opinions about setting your lever drags on strike while you are trolling or backing off a bit and then pushing up the drag pressure after hook up. You can practice this and see what is best for you.

If you notice your bites are coming up tight to the boat than you will probably want to pull your longer baits in a little to increase your chances of multiple hook ups. The opposite is true as well, if your bites are coming from your long lines than drop everything back a little bit.', 'Female bluefin are thought to produce up to 30 million eggs. Bluefin tuna spawn in two widely separated areas. One spawning ground exists in the western Mediterranean, particularly in the area of the Balearic Islands. The other important spawning ground of the bluefin is the Gulf of Mexico. Pop-up satellite tracking results appear to confirm in large measure the belief held by many scientists and fishermen that although bluefin that were spawned in each area may forage widely across the Atlantic, they return to the same area to spawn.

Bluefin group together in large concentrations to spawn, and at such times are highly vulnerable to commercial fishing. This is particularly so in the Mediterranean where the groups of spawning bluefin can be spotted from the air by light aircraft and purse seines directed to set around the schools.

The western and eastern populations of Atlantic bluefin tuna are thought to mature at different ages. It is thought that bluefin born in the east reach maturity a year or two earlier than those spawned in the west.

', 'The bluefin tuna typically hunts small fish such as sardines, herring and mackerel and invertebrates like squid and crustaceans. Bluefin dive to depths of 1,600 ft (500 meters) and they can reach speeds upwards of 40 miles per hour (64 km/h).', 'Ocean', 'Stamina', '1496 lb.
Ken Fraser,
Nova Scotia,
1979', 'Bluefin Tuna WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, baits_and_techniques, spawning_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Tuna, Dogtooth', 'Dogtooth Unicolor, Dog Teeth Tuna, Pegtooth Tuna, Whiteflesh Tuna, White Tuna, Scaleless Tuna, Tunny, RuppSl''s Bonito.', 'Dogtooth tuna are members of the mackerel family. Distinguishing features include a streamlined body with a large head and a mouth that contains twenty sharp dog-like teeth per jaw. They have two dorsal fins;

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, baits_and_techniques, spawning_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Tuna, Skipjack', 'Striped Tuna, Striped Tunny, Skipjack, Oceanic Skipjack, Skipper, Skippy, Bonito, Ocean Bonito, Oceanic Bonito, Pacific Bonito, Striped Bonito, Striped Bellied Bonito, White Bonito, Striped Belly Tunny, Club Mackerel and Watermelon', 'Skipjack tuna can be distinguished by the presence of four to seven dark, longitudinal stripes on their bellies. They have silvery flanks and bellies an d have short fins. Their dark blue backs are accentuated by a clearly defined area of green above the sector fins which fades away approaching the mid-body.', 'Scombridae', 'Katsuwonus pelamis', 'Least Concern', 'Skipjack tuna usually frequent deep coastal and oceanic waters. It is common throughout the tropical Atlantic, south to Argentina and may range as far north as Massachusetts in the summer months. Skipjack Tunas are schooling, pelagic, migratory, deep water species, and are even known to frequently school together with Blackfin and Yellowfin Tuna. Its common name – the Arctic bonito – implies that the Skipjack is a misnomer, but unlike the Dogtooth Tuna, this one is not in fact a bonito, but a true tuna specimen.

Although mainly found in deep offshore waters, yellowfin tuna may approach shore when suitable conditions exist. Mid-ocean islands such as the Hawaiian archipelago, other island groups in the Western Pacific, Caribbean, and Maldives islands Indian Ocean, as well as the volcanic islands of the Atlantic such as Ascension Island and Saint Helena, often harbor yellowfin feeding on the baitfish these spots concentrate close to the shoreline. Yellowfin may venture well inshore of the continental shelf when water temperature and clarity are suitable and food is abundant.

Yellowfin tuna often travel in schools with similarly sized companions. They sometimes school with other tuna species and mixed schools of small yellowfin, and skipjack tuna, in particular, are commonplace. They are often associated with various species of dolphins or porpoises, as well as with larger marine creatures such as whales and whale sharks. They also associate with drifting flotsam such as logs and pallets, and sonic tagging indicates some follow moving vessels. Hawaiian yellowfins associate with anchored fish aggregation devices and with certain sections of the 50-fathom curve.', 'Anglers be forewarned - the skipjack tuna is a gregarious fish, a champion fighter and a very fast swimmer.

It will strike trolled strip baits, feathers, spoons, plugs, or small whole baits. Some are taken by casting, jigging or live bait fishing off shore.', 'Skipjack tuna is a batch spawner. Spawning occurs year-round in equatorial waters, but it gets more seasonal further away from the equator.', 'The skipjack tuna feeds near the surface, sometimes forming schools composed of up to 50,000 or more individuals. It feeds on fish, crustaceans, cephalopods, and mollusks. It is also an important prey species for large pelagic fishes and sharks who sometimes consume the skipjack during large communal feeding sessions.', 'Ocean', 'Speed', '45 lb 4 oz,
Brian Evans,
Flathead Bank, Baja California, Mexico,
11/16/1996', 'Skipjack Tuna WR');

